290	    /// @inheritdoc IRaffle
291	    function enableRefunds() external override nonReentrant {
292	        uint256 deadline;
293	
294	        if (status == Status.Active) {
295	            if (totalEntries == 0) {
296	                deadline = endTime;
297	                if (msg.sender != sponsor && block.timestamp < deadline) {
298	                    revert RefundsNotAvailable(deadline, block.timestamp);
299	                }
300	            } else {
301	                deadline = drawRequestDeadline();
302	                if (block.timestamp < deadline) revert RefundsNotAvailable(deadline, block.timestamp);
303	            }
304	        } else if (status == Status.Drawing) {
305	            deadline = callbackDeadline();
306	            if (block.timestamp < deadline) revert RefundsNotAvailable(deadline, block.timestamp);
307	        } else {
308	            revert InvalidStatus(status);
309	        }
310	
311	        uint256 liability = unsettledPot;
312	        unsettledPot = 0;
313	        remainingRefundLiability = liability;
314	        status = Status.Refunding;
315	        emit RefundsEnabled(msg.sender, liability);
316	    }
