323	    /// @inheritdoc IRaffle
324	    function redeemWinningTicket(uint256 ticketId) external override nonReentrant returns (uint256 cashAmount) {
325	        if (winnerRedeemed) revert WinningTicketAlreadyRedeemed();
326	        Status result = status;
327	        if (result != Status.NftWon && result != Status.CashWon) revert InvalidStatus(result);
328	
329	        if (!settlementComplete) {
330	            _settleWinningTicket(ticketId);
331	        } else if (ticketId != winningTicketId) {
332	            revert WinningTicketMismatch(ticketId, winningTicketId);
333	        }
334	
335	        address winner = ownerOf(ticketId);
336	        if (msg.sender != winner) revert NotTicketOwner(ticketId, msg.sender, winner);
337	
338	        winnerRecipient = winner;
339	        winnerRedeemed = true;
340	        _burn(ticketId);
341	
342	        address deliveredPrizeToken = address(0);
343	        uint256 deliveredPrizeTokenId = 0;
344	        if (result == Status.NftWon) {
345	            if (prizeClaimed) revert PrizeAlreadyClaimed();
346	            prizeClaimed = true;
347	            deliveredPrizeToken = address(prizeToken);
348	            deliveredPrizeTokenId = prizeTokenId;
349	            prizeToken.transferFrom(address(this), winner, deliveredPrizeTokenId);
350	            if (prizeToken.ownerOf(deliveredPrizeTokenId) != winner) {
351	                revert PrizeDeliveryVerificationFailed(winner);
352	            }
353	        } else {
354	            cashAmount = winnerProceeds;
355	            if (cashAmount == 0) revert NoWinnerProceeds();
356	            winnerProceeds = 0;
357	            _transferQuote(winner, cashAmount);
358	        }
359	
360	        emit WinningTicketRedeemed(ticketId, winner, result, cashAmount, deliveredPrizeToken, deliveredPrizeTokenId);
361	    }
