363	    /// @inheritdoc IRaffle
364	    function refundTickets(uint256[] calldata ticketIds) external override nonReentrant returns (uint256 amount) {
365	        _requireStatus(Status.Refunding);
366	        uint256 ticketQuantity = ticketIds.length;
367	        if (ticketQuantity == 0 || ticketQuantity > RaffleConstants.MAX_REFUND_TICKET_BATCH_SIZE) {
368	            revert InvalidTicketBatchSize(ticketQuantity, RaffleConstants.MAX_REFUND_TICKET_BATCH_SIZE);
369	        }
370	
371	        uint256 aggregateEntries = 0;
372	        for (uint256 index; index < ticketQuantity; ++index) {
373	            uint256 ticketId = ticketIds[index];
374	            address owner = ownerOf(ticketId);
375	            if (msg.sender != owner) revert NotTicketOwner(ticketId, msg.sender, owner);
376	
377	            (uint128 firstEntry, uint128 lastEntry) = ticketRange(ticketId);
378	            aggregateEntries += uint256(lastEntry) - uint256(firstEntry) + 1;
379	            _burn(ticketId);
380	        }
381	
382	        amount = aggregateEntries * ENTRY_PRICE;
383	        remainingRefundLiability -= amount;
384	        _transferQuote(msg.sender, amount);
385	        uint256 liabilityAfter = remainingRefundLiability;
386	        emit TicketsRefunded(msg.sender, ticketQuantity, aggregateEntries, amount, liabilityAfter);
387	    }
