        require(usdc.balanceOf(address(raffle)) == 50e6, "only fee left");
    }

    /// Control: the sponsor keeps an option. In CashWon it unpauses and takes the NFT back plus 15%.
    function testSponsorOptionInCashWon() external {
        vm.warp(1_700_000_000);
        usdc = new MockUSDC();
        wrapper = new MockWrapper();
        factory = new RaffleFactory(address(usdc), address(wrapper), treasury);
        vm.startPrank(sponsor);
        nft = new PausableNFT();
        nft.mint(sponsor, 1);
        nft.approve(address(factory), 1);
        raffle = Raffle(payable(factory.createRaffle(IRaffleFactory.CreateRaffleParams({
            sponsorRecipient: sponsorRecipient,
            prizeToken: address(nft),
            prizeTokenId: 1,
            reserveEntries: 2000,
            endTime: uint64(block.timestamp + 7 days)
        }))));
        vm.stopPrank();
        usdc.mint(buyer1, 1000e6);
        vm.startPrank(buyer1);
        usdc.approve(address(raffle), 1000e6);
        raffle.buyEntries(buyer1, 1000);
        vm.stopPrank();

        vm.warp(raffle.endTime());
        vm.prank(sponsor);
        nft.pause();
        vm.deal(address(this), 1 ether);
        raffle.requestDraw{ value: 0.01 ether }();
        wrapper.fulfill(raffle.vrfRequestId(), 5);
        require(raffle.status() == IRaffle.Status.CashWon, "cashwon");

        vm.prank(sponsor);
        nft.unpause();
        raffle.releaseSponsorPrize();
        require(nft.ownerOf(1) == sponsorRecipient, "nft back");
        vm.prank(buyer1);
        raffle.redeemWinningTicket(1);
        raffle.releaseSponsorProceeds();
        require(usdc.balanceOf(sponsorRecipient) == 150e6, "15%");
        require(usdc.balanceOf(buyer1) == 800e6, "80%");
    }

    receive() external payable { }
}
